PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?place ?placeLabel ?birthPlaceLiteral WHERE {
  dbr:Islam_Shah_Suri dbp:father ?father .
  OPTIONAL { ?father dbo:birthPlace ?place . }
  OPTIONAL { ?father dbp:birthPlace ?birthPlaceLiteral . }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(langMatches(lang(?fatherLabel), "EN")) }
  OPTIONAL { ?place rdfs:label ?placeLabel . FILTER(langMatches(lang(?placeLabel), "EN")) }
}

